J'ai ce code dans mon ProfileUIController qui affiche les stats du joueur en temps réel depuis Firestore. Est-ce qu'il est correct ?

public class ProfileUIController : MonoBehaviour
{
    public TMP_Text statsText;
    private IDisposable listener;
    void Start()
    {
        var uid = FirebaseAuth.DefaultInstance.CurrentUser.UserId;
        listener = FirebaseFirestore.DefaultInstance.Collection("profiles").Document(uid).Listen(snapshot => {
            var profile = snapshot.ConvertTo<Profile>();
            statsText.text = $"Gold: {profile.gold}";
        });
    }
    void OnDestroy() { listener?.Dispose(); }
}

